package edu.pse.beast.datatypes.electioncheckparameter;

import java.util.List;

/**
 * 
 * @author Lukas
 *
 */
public class ElectionCheckParameter {
    private final List<Integer> amountVoters;
    private final List<Integer> amountCandidates;
    private final List<Integer> amountSeats;
    private final TimeOut timeOut;
    private final Integer processes;
    private final String argument;

    /**
     * 
     * @param amountVoters the list that specifies the range of voters
     * @param amountCandidates the list that specifies the range of candidates
     * @param amountSeats the list that specifies the range of seats
     * @param timeOut the timeout that specifies how long the checker should run
     * @param processes max number of processes of the checker
     * @param argument the arguments given by the user
     */
    public ElectionCheckParameter(List<Integer> amountVoters, List<Integer> amountCandidates, 
            List<Integer> amountSeats, TimeOut timeOut, Integer processes, String argument) {
        this.amountVoters = amountVoters;
        this.amountCandidates = amountCandidates;
        this.amountSeats = amountSeats;
        this.timeOut = timeOut;
        this.processes = processes;
        this.argument = argument;
    }

    /**
     * 
     * @return the list that specifies the range of voters
     */
    public List<Integer> getAmountVoters() {
        return amountVoters;
    }

    /**
     * 
     * @return the list that specifies the range of candidates
     */
    public List<Integer> getAmountCandidates() {
        return amountCandidates;
    }

    /**
     * 
     * @return the list that specifies the range of seats
     */
    public List<Integer> getAmountSeats() {
        return amountSeats;
    }

    /**
     * 
     * @return the timeout that specifies how long the checker should run
     */
    public TimeOut getTimeout() {
        return timeOut;
    }

    /**
     *
     * @return the amount of processes the user wishes to run at the same time
     */
    public Integer getProcesses() {
        return processes;
    }

    /**
     * 
     * @return the String that defines the advanced options 
     */
    public String getArgument() {
        return argument;
    }
}

package com.jungdam.invitation.dto.response;

import com.jungdam.invitation.domain.vo.Status;

public class UpdateInvitationResponse {

    private final Long albumId;
    private final Long invitationId;
    private final Status status;

    public UpdateInvitationResponse(Long albumId, Long id,
        Status status) {
        this.albumId = albumId;
        this.invitationId = id;
        this.status = status;
    }

    public static UpdateInvitationResponseBuilder builder() {
        return new UpdateInvitationResponseBuilder();
    }

    public Long getAlbumId() {
        return albumId;
    }

    public Long getInvitationId() {
        return invitationId;
    }

    public Status getStatus() {
        return status;
    }

    public static class UpdateInvitationResponseBuilder {

        private Long albumId;
        private Long invitationId;
        private Status status;

        private UpdateInvitationResponseBuilder() {
        }

        public UpdateInvitationResponseBuilder albumId(final Long albumId) {
            this.albumId = albumId;
            return this;
        }

        public UpdateInvitationResponseBuilder invitationId(final Long invitationId) {
            this.invitationId = invitationId;
            return this;
        }

        public UpdateInvitationResponseBuilder status(final Status status) {
            this.status = status;
            return this;
        }

        public UpdateInvitationResponse build() {
            return new UpdateInvitationResponse(this.albumId, this.invitationId, this.status);
        }
    }
}

package net.canarymod.api.entity.living.monster;

import net.canarymod.api.world.blocks.Block;

/**
 * Enderman Wrapper
 *
 * @author Jason (darkdiplomat)
 */
public interface Enderman extends EntityMob {

    /**
     * Gets the {@link Block} the Enderman carries
     * NOTE: the World and Position data of the block may be based on the Enderman's current location at the time the method is called
     *
     * @return the block being carried
     */
    Block getCarriedBlock();

    /**
     * Get the block id for the block this Enderman carries
     *
     * @return block id
     *
     * @deprecated Use {@link #getCarriedBlock} instead
     */
    @Deprecated
    short getCarriedBlockID();

    /**
     * Sets the Block the Enderman carries
     *
     * @param block
     *         the block to set
     */
    void setCarriedBlock(Block block);

    /**
     * Sets the Block ID for the block this Enderman carries
     *
     * @param blockId
     *         the block id
     *
     * @deprecated Use {@link #setCarriedBlock(net.canarymod.api.world.blocks.Block)} instead
     */
    @Deprecated
    void setCarriedBlockID(short blockId);

    /**
     * Gets the metadata of the Block the Enderman carries
     *
     * @return metadata
     *
     * @deprecated Block MetaData has gone away, use {@link #getCarriedBlock()} instead
     */
    @Deprecated
    short getCarriedBlockMetaData();

    /**
     * Sets the metadata of the Block
     *
     * @param metadata
     *         the data for the block being carried
     *
     * @deprecated Block MetaData has gone away, use {@link #setCarriedBlock(net.canarymod.api.world.blocks.Block)} instead
     */
    @Deprecated
    void setCarriedBlockMetaData(short metadata);

    /**
     * Teleport the Enderman to a random position nearby
     *
     * @return {@code true} if successful; {@code false} if not
     */
    boolean randomTeleport();

    /**
     * Gets if the Enderman is screaming
     *
     * @return {@code true} if screaming; {@code false} if not
     */
    boolean isScreaming();

    /**
     * Sets if the Enderman is screaming
     *
     * @param screaming
     *         {@code true} for screaming; {@code false} for not
     */
    void setScreaming(boolean screaming);
}

package dev.jeka.core.api.utils;

/**
 * Utility class to deal with {@link Throwable}
 */
public final class JkUtilsThrowable {

    private JkUtilsThrowable() {
        // prevent instantiation
    }

    /**
     * Returns the specified exception itself if it is an unchecked exception
     * (extending {@link RuntimeException}). Otherwise returns a new
     * {@link RuntimeException} wrapping the exception passed as argument.
     */
    public static RuntimeException unchecked(Exception e) {
        if (e instanceof RuntimeException) {
            return (RuntimeException) e;
        }
        return new RuntimeException(e);
    }

    /**
     * Same as {@link #unchecked(Exception)} but specifying an error message.
     */
    public static RuntimeException unchecked(Throwable e, String message) {
        if (e instanceof RuntimeException) {
            return (RuntimeException) e;
        }
        return new RuntimeException(message, e);
    }

    /**
     * Returns <code>true</code> if the specified throwable has the specified cause exception class
     * along the specified message in its chain.
     */
    public static boolean nestedContains(Throwable throwable, Class<Exception> exceptionClass,
            String message) {
        if (throwable.getClass().equals(exceptionClass) && message.equals(throwable.getMessage())) {
            return true;
        }
        if (throwable.getCause() == null) {
            return false;
        }
        return nestedContains(throwable.getCause(), exceptionClass, message);
    }

    /**
     * Returns <code>true</code> if the specified throwable has the specified cause exception class
     * in its chain.
     */
    public static boolean isInCause(Throwable throwable, Class<? extends Throwable> causeClass) {
        if (causeClass.isAssignableFrom(throwable.getClass())) {
            return true;
        }
        final Throwable cause = throwable.getCause();
        if (cause == null) {
            return false;
        }
        return isInCause(cause, causeClass);
    }

}

