package javax.faces.state.scxml.model;

/**
 * Plain Java Object {@link ParsedValue} implementation mapped from a json string
 * <p>
 * For serialization back to XML flag {@link #isCDATA()} is recorded to wrap the json string in a CDATA section if needed.
 * </p>
 */
public class JsonValue implements ParsedValue {

    /**
     * The Java Object mapped from a json string
     */
    private final Object jsonObject;

    /**
     * The flag indicating if the json string requires wrapping in a CDATA section when writing out to XML
     */
    private final boolean cdata;

    /**
     *
     * @param jsonObject
     * @param cdata
     */
    public JsonValue(final Object jsonObject, final boolean cdata) {
        this.jsonObject = jsonObject;
        this.cdata = cdata;
    }

    @Override
    public final ValueType getType() {
        return ValueType.JSON;
    }

    /**
     * @return true if the json string requires wrapping in a CDATA section when writing out to XML
     */
    public final boolean isCDATA() {
        return cdata;
    }

    @Override
    public final Object getValue() {
        return jsonObject;
    }
}

package game.message.toServer;

import game.model.game.model.ServerGameModel;
import game.model.game.model.worldObject.entity.Entity;

/**
 * Message sent by a client to tell the server to stop the player
 * on the game map.
 */
public class StopRequest extends ActionRequest {

    /**
     * ID to distinguish player that sent the message.
     */
    private long id;

    /**
     * Constructor for the stop message.
     * @param id player ID that send the message
     */
    public StopRequest(long id) {
        super();
        this.id = id;
    }

    /**
     * Default constructor needed for serialization.
     */
    public StopRequest() {

    }

    /**
     * Stops the player's movement.
     * @param model the game model on the game server
     */
    @Override
    public void executeServer(ServerGameModel model) {
        if(model.getEntity(id) != null && model.getEntity(id).has(Entity.EntityProperty.VELOCITY))
            model.getEntity(id).setVelocity(model.getEntity(id).getVelocity().withMagnitude(0));
    }
}

package core.action.cache;

import core.neighbor.Neighbor;

import java.util.HashSet;

public class LockedNeighborCache {
    private final HashSet<Neighbor> isVisited = new HashSet<>();
    private final HashSet<Neighbor> isPassed = new HashSet<>();

    public void clear() {
        isPassed.clear();
    }

    public void visit(Neighbor neighbor) {
        isVisited.add(neighbor);
    }

    public boolean isVisited(Neighbor neighbor) {
        return isVisited.contains(neighbor);
    }

    public void found(Neighbor neighbor) {
        isPassed.add(neighbor);
    }

    public boolean isFound(Neighbor neighbor) {
        return isPassed.contains(neighbor);
    }

    public void resetTrail() {
        isVisited.clear();
    }
}

