package ru.job4j.comparator;

/**
 * Получение компаратора. Метод compare().
 * Задача написать два метода которые сравнивают два числа, первый сравнивает
 * в прямом порядке, второй в обратном порядке. Т.е. первый должен быть
 * аналогичен Integer.compare(),
 * а второй должен возвращать обратным ему результат.
 *
 * @author ViktorJava (<EMAIL>)
 * @version 0.1
 * @since 25.11.2020
 */
public class CompareMethod {
    /**
     * Метод сравнивает два числа в прямом порядке.
     *
     * @param first  Первое число.
     * @param second Второе число.
     * @return Порядок двух чисел:
     * -1. если результат отрицательный, то это значит, первое число
     * идет раньше чем второе число.
     * 0. если результат равен 0, то это значит, что порядок не важен.
     * 1. если результат положительный, то это значит,
     * что первое число идет после второго числа.
     */
    public static int ascendingCompare(int first, int second) {
        int result = Integer.compare(first, second);
        return result;
    }

    /**
     * Метод сравнивает два числа в обратном порядке.
     * -1. если результат отрицательный, то это значит, первое число
     * идет после второго числа.
     * 0. если результат равен 0, то это значит, что порядок не важен.
     * 1. если результат положительный, то это значит,
     * что первое число идет раньше второго числа.
     *
     * @param first  Первое число.
     * @param second Второе число.
     * @return Порядок двух чисел.
     */
    public static int descendingCompare(int first, int second) {
        int result = Integer.compare(second, first);
        return result;
    }
}

package summers;

import java.util.Objects;

/**
 * A worker that can compute the sum of the elements of an array in background
 *
 * @author emanuele
 */
public class BackgroundArraySummer implements Worker, Runnable {

    /**
     * The array of values to be summed
     */
    private final double[] values;
    /**
     * actual result
     */
    private double sum = 0.0;
    /**
     * number of values summed so far
     */
    private int summed = 0;
    /**
     * Whether work has been started
     */
    private boolean started = false;

    /**
     * Creates a new BackgroundArraySummer
     *
     * @param values array of values to be summed
     */
    public BackgroundArraySummer(double[] values) {
        this.values = Objects.requireNonNull(values, "Give me something real, please!!!");
    }

    @Override
    public void work() {
        if (!started) {
            debug("Putting myself to work...");
            // if "this" is runnable (yes it is)
            // new Thread(this).start();
            /* with lambdas
            new Thread(() -> {
                while (!isCompleted()) {
                    sum += values[summed++];
                }
                debug("Work is completed...");
            }).start();
             */
            // creates and start a new thread of execution
            new Thread(new Runnable() {
                // code to be run
                @Override
                public void run() {
                    while (!isCompleted()) {
                        sum += values[summed++];
                    }
                    debug("Work is completed...");
                }
            }).start();
            started = true;
        } else {
            if (!isCompleted()) {
                debug("Still working, please wait a second!!!");
            } else {
                debug("There's nothing else to be done !!!");
            }
        }
    }

    @Override
    public boolean isCompleted() {
        return summed == values.length;
    }

    @Override
    public Object getResult() {
        return isCompleted() ? sum : null;
    }

    /**
     * the code to be run by the new thread
     */
    @Override
    public void run() {
        while (!isCompleted()) {
            sum += values[summed++];
        }
        debug("Work is completed...");
    }

}

// Definition for a binary tree node.
  public class TreeNode {
      int val;
      TreeNode left;
      TreeNode right;
      TreeNode() {}
      TreeNode(int val) { this.val = val; }
      TreeNode(int val, TreeNode left, TreeNode right) {
          this.val = val;
          this.left = left;
          this.right = right;
      }
  }
 //Program to perform searching in BST
class Solution {
    public TreeNode searchBST(TreeNode root, int val) {
      // run while roop with condition where root is not null
      //if the root will be null at first, it will return null
        while(root!=null)
        {
            if(val==root.val)
                return root;
            else if(val<root.val)
                root=root.left;
            else
                root=root.right;
        }
        return null;
    }
}

