package com.telenav.osv.common.ui.loader;

import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import androidx.annotation.LayoutRes;

/**
 * Popup base class which holds all functionality for adding/removing a popup layout to/from a container.
 * @author horatiuf
 */

abstract class PopupBase {

    /**
     * Inflated view that will represent the popup.
     */
    ViewGroup panel;

    /**
     * Returns a boolean indicating if the dialog is visible or not.
     * @return if true, layout is visible
     */
    public boolean isVisible() {
        return panel != null && panel.getVisibility() == View.VISIBLE;
    }

    /**
     * Inflates the layout in the wanted parentView.
     */
    void addViewToPopupFrame(ViewGroup container) {
        if (panel != null) {
            return;
        }
        if (container != null) {
            panel = (ViewGroup) ((LayoutInflater) container.getContext().getSystemService(Context.LAYOUT_INFLATER_SERVICE)).inflate(getLayoutId(), null);
            container.addView(panel, container.getChildCount());
            panel.setVisibility(View.GONE);
        }
    }

    /**
     * Removes the dialog from the popup frame layout
     */
    void removeViewFromPopupFrame(ViewGroup container) {
        if (container != null && panel != null) {
            container.removeView(panel);
            panel = null;
        }
    }

    /**
     * @return the layout's id that will be inflated
     */
    @LayoutRes
    abstract int getLayoutId();

    /**
     * Shows the popup
     */
    abstract void show(ViewGroup container);

    /**
     * Shows the popup
     */
    abstract void show(ViewGroup container, int fadeInTimeMs);

    /**
     * Hides the popup
     */
    abstract void hide(ViewGroup container);
}

package com.nucleus.scene;

import java.util.ArrayList;

/**
 * Traverses the nodetree in a breadth first manner.
 *
 */
public class BreadthFirstNodeIterator extends NodeIterator {

    ArrayList<Node> children;

    /**
     * Creates a new nodeiterator
     * 
     * @param start
     * @throws IllegalArgumentException If start is null
     */
    public BreadthFirstNodeIterator(Node start) {
        super(start);
    }

    @Override
    public boolean hasNext() {
        // TODO Auto-generated method stub
        return false;
    }

    @Override
    public Node next() {
        if (children == null) {
            children = start.getChildren();
        }
        return null;
    }

    /**
     * Returns the node and childnodes as breadth first list
     * 
     * @param start
     * @return
     */
    public ArrayList<Node> breadthFirstList(Node start) {
        return addNode(null, null, start);
    }

    private ArrayList<Node> addNode(ArrayList<Node> result, ArrayList<Node> children, Node node) {
        if (result == null) {
            result = new ArrayList<>();
        }
        if (children == null) {
            children = new ArrayList<>();
        }
        result.add(node);
        children.addAll(node.getChildren());
        addChildren(result, children, node);
        return result;
    }

    private void addChildren(ArrayList<Node> result, ArrayList<Node> parents, Node parent) {
        ArrayList<Node> children = new ArrayList<>();
        for (Node n : parents) {
            addNode(result, children, n);
        }
    }

}

package io.github.quickmsg.common.metric;

import reactor.core.scheduler.Scheduler;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.LongAdder;

/**
 * @author luxurong
 */
public abstract class WindowCounter implements MetricCounter, Runnable {

    private final LongAdder sumCountAdder = new LongAdder();

    private final LongAdder windowCountAdder = new LongAdder();


    private final MetricBean metricBean;


    @Override
    public MetricBean getMetricBean() {
        return this.metricBean;
    }

    public WindowCounter(MetricBean metricBean, Integer time, TimeUnit timeUnit, Scheduler scheduler) {
        this.metricBean = metricBean;
        scheduler.schedulePeriodically(this, time, time, timeUnit);
        scheduler.start();
    }

    @Override
    public void reset() {
        sumCountAdder.reset();
        windowCountAdder.reset();
    }

    public void run() {
        windowCountAdder.reset();
    }

    @Override
    public long getCounter() {
        return this.sumCountAdder.sum();
    }


    public long getAllCount() {
        return this.sumCountAdder.sum();
    }


    @Override
    public void increment() {
        sumCountAdder.increment();
        callMeter(sumCountAdder.sum());
    }

    @Override
    public void decrement() {
        throw new UnsupportedOperationException("WindowCounter not support decrement");
    }


    public long getWindowCount() {
        return windowCountAdder.sum();
    }


}

package org.owasp.esapi.core.encoding;

/**
 * The basic functionality of the EncodingContext is to encode a single character to it's correct format for the
 * current Context. For example, if this implementation was meant to encode characters for HTML it would encode the {@literal<}
 * character and return the value &amp;lt;.
 *
 * @author <NAME> (<EMAIL>) https://www.ContrastSecurity.com
 */
public interface EncodingContext {
    /**
     * Encodes a single character returning either the character itself or the encoded version of the character for the
     * current context.
     *
     * @param c The character to be encoded.
     * @return Either the character itself or the encoded representation of the character.
     * @throws UnencodableCharacterException If the supplied character cannot be encoded in the current context. An example
     *                                       could be a UTF-16 character passed into a UTF-8 encoder implementation.
     */
    String encode(char c) throws UnencodableCharacterException;

    /**
     * Decodes the supplied string
     * @param str
     * @return
     * @throws EncodingException
     */
    String decode(String str) throws EncodingException;

    /**
     * Returns the character sequence that marks the beginning of a control sequence. For example in HTML this would simply
     * return the '&amp;' character.
     *
     * @return The character or character sequence that marks the beginning of a control sequence.
     */
    String getControlSequence();

    /**
     * Returns the character or character sequence that marks the end of a control sequence. For example in HTML this would
     * simply return the ';' character.
     *
     * @return The character or character sequence that marks the end of a control sequence.
     */
    String getControlSequenceEnd();
}

package org.jessenpan.leetcode.linkedlist;

import java.util.HashSet;
import java.util.Set;

/**
 * @author jessenpan
 * tag:linkedlist
 */
public class S82RemoveDuplicatesFromSortedListII {

    public static class ListNode {

        int val;
        ListNode next;

        ListNode(int x) { val = x; }

        ListNode(int x, ListNode next) {
            this.val = x;
            this.next = next;
        }
    }

    public ListNode deleteDuplicates(ListNode head) {
        Set<Integer> record = new HashSet<>();
        ListNode newHead = new ListNode(0);
        ListNode current = newHead;

        while (head != null) {
            ListNode next = head.next;
            if (!record.contains(head.val) && next == null) {
                record.add(head.val);
                current.next = head;
                current = current.next;
            } else if (next != null && !record.contains(head.val) && head.val != next.val) {
                record.add(head.val);
                current.next = head;
                current = current.next;
            } else {
                record.add(head.val);
            }
            head = head.next;
        }
        current.next = null;

        return newHead.next;
    }

}

