     * @param level   the level
     * @param message the message
     */
    default void log(Level level, String message) {
        log(new LogEvent(message, level, null, this));
    }


    /**
     * Thrown.
     *
     * @param e the e
     */
    default void thrown(Throwable e) {
        thrown("Exception/Error occurred", e);
    }


